    18	/** Centre a real low trunk ring; generated stems may bend away from local Y. */
    19	function lowerTrunkAim(geometry: THREE.BufferGeometry): THREE.Vector3 {
    20	  const cached = trunkAimCache.get(geometry);
    21	  if (cached) return cached;
    22	  const positions = geometry.getAttribute('position');
    23	  const uv = geometry.getAttribute('uv');
    24	  let aim = new THREE.Vector3(0, 1.1, 0);
    25	  let best = Infinity;
    26	  if (positions && uv) {
    27	    for (let start = 0; start < positions.count; start++) {
    28	      if (Math.abs(uv.getX(start)) > 1e-5) continue;
    29	      const center = new THREE.Vector3();
    30	      let count = 0;
    31	      for (let i = start; i < positions.count; i++) {
    32	        if (i > start && Math.abs(uv.getX(i)) < 1e-5) break;
    33	        if (uv.getX(i) >= .99999) break; // duplicate seam vertex
    34	        center.add(new THREE.Vector3().fromBufferAttribute(positions, i));
    35	        count++;
    36	      }
