    38	      center.divideScalar(count);
    39	      if (center.y < .35 || center.y > 3) continue;
    40	      const cost = Math.abs(center.y - 1.1) + Math.hypot(center.x, center.z) * .5;
    41	      if (cost < best) { best = cost; aim = center; }
    42	    }
    43	  }
    44	  trunkAimCache.set(geometry, aim);
    45	  return aim;
    46	}
