    48	/** A real tree and dry local return route, chosen around the site being built. */
    49	export function planConstructionTree(
    50	  targets: readonly TreePickTarget[],
    51	  player: THREE.Vector3,
    52	  home: THREE.Vector3,
    53	  terrain: SpawnTerrainQuery,
    54	  planetSize: number,
    55	  harvested: (x: number, y: number, z: number) => boolean
    56	): ConstructionTreePlan | null {
    57	  const face = dominantFaceForPosition(home);
    58	  const up = FACE_NORMALS[face];
    59	  const seen = new Set<string>();
    60	  const candidates: Array<{ coord: [number, number, number]; root: THREE.Vector3; aim: THREE.Vector3; cost: number }> = [];
    61	  for (const { mesh, slotVoxel } of targets) {
    62	    for (const [slot, coord] of slotVoxel.entries()) {
    63	      const key = coord.join(',');
    64	      if (seen.has(key) || harvested(...coord)) continue;
    65	      seen.add(key); // TreeField publishes trunk before leaves for each variant.
    66	      const root = voxelCoordToWorld(...coord);
    67	      if (dominantFaceForPosition(root) !== face || root.distanceTo(home) > 40) continue;
    68	      const matrix = new THREE.Matrix4();
    69	      mesh.getMatrixAt(slot, matrix);
    70	      // Read the rendered trunk's own transform (including tilt/scale), above
    71	      // ground flora. The old root+up1.2 target often selected stone or flowers.
    72	      const aim = lowerTrunkAim(mesh.geometry).clone().applyMatrix4(matrix).applyMatrix4(mesh.matrixWorld);
    73	      candidates.push({ coord: [...coord], root, aim,
    74	        cost: player.distanceTo(root) + root.distanceTo(home) });
    75	    }
    76	  }
    77	  candidates.sort((a, b) => a.cost - b.cost);
    78	  const navigationTerrain = {
    79	    isSolidVoxel: terrain.shouldVoxelExist,
    80	    isWaterVoxel: terrain.isWaterVoxel,
    81	    isHazardousVoxel: (x: number, y: number, z: number) => terrain.generateBlockForPosition(x, y, z) === 'lava'
    82	  };
    83	  for (const candidate of candidates.slice(0, 12)) {
    84	    const approach = interactionApproachGoal(player, candidate.root, up, 5.5, terrain, planetSize);
    85	    if (!approach) continue;
    86	    const options = { face, allowJetpackCrossing: false, maxVisitedCells: 800 } as const;
    87	    const outward = planAgentSurfaceRoute(navigationTerrain, planetSize, player, approach, options);
    88	    if (outward.mode !== 'walk') continue;
    89	    const returning = planAgentSurfaceRoute(navigationTerrain, planetSize, approach, home, options);
    90	    if (returning.mode !== 'walk') continue;
    91	    return { ...candidate, approach };
    92	  }
    93	  return null;
    94	}

